from pathlib import Path
import sys, re, subprocess, tempfile
p=Path(sys.argv[1] if len(sys.argv)>1 else 'beta.html')
s=p.read_text(encoding='utf-8')
patch='''function primer173Init(host){if($('primer173'))return;const e=document.createElement('details');e.id='primer173';e.className='analysis';e.innerHTML='<summary><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 5C9 3 5 3 2 4v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1v15"/></svg> Deck Primer</summary><div id="primer173Body"></div>';host.append(e)}
function primer173Paint(){const d=state.decks.find(x=>x.id===active),b=$('primer173Body');if(!d||!b)return;try{const z=deckStats(d),rows=z.rows||[],leaders=z.leaders||[],known=rows.filter(x=>x.c.metaReady),total=rows.reduce((a,x)=>a+x.n,0),covered=known.reduce((a,x)=>a+x.n,0),labels={lands:'Lands',ramp:'Mana development',draw:'Card advantage',interaction:'Interaction',protection:'Protection',creatures:'Creatures',recovery:'Recovery',evasion:'Evasion'},roleKeys=Object.keys(labels),counts=Object.fromEntries(roleKeys.map(k=>[k,known.reduce((a,x)=>a+(roles(x.c)[k]?x.n:0),0)])),themes=order151(z).slice(0,4),explicit=[d.primary15,d.secondary15].filter(Boolean),cardButton=(c,why)=>'<button type="button" class="primer173Card" data-pcard="'+esc(c.id||'')+'" data-pname="'+esc(c.name)+'"><span>'+esc(c.name)+'</span><small>'+esc(why)+'</small><span class="primer173Cost">'+esc(c.manaCost||'')+'</span></button>';let leaderHtml=leaders.map(c=>cardButton(c,'Commander')+'<p class="primer173Rules">'+esc(c.rules||'Saved rules unavailable; open card information.')+'</p>').join('')||'<p>No commander configured.</p>';let groups=roleKeys.filter(k=>k!=='lands'&&counts[k]>0).map(k=>{let seen=new Set();let cards=known.filter(x=>roles(x.c)[k]).sort((a,b)=>(b.n-a.n)||((a.c.mv??99)-(b.c.mv??99))).filter(x=>{if(seen.has(x.c.name))return false;seen.add(x.c.name);return true}).slice(0,3);return '<details class="primer173Group"><summary>'+esc(labels[k])+' · '+counts[k]+' copies</summary>'+cards.map(x=>cardButton(x.c,labels[k]+' candidate · '+x.n+' assigned')).join('')+'</details>'}).join('');b.innerHTML='<h2>Deck Primer</h2><p class="muted">Automatic, rule-based guide · '+esc(d.name)+' · '+esc(d.format)+'</p><p>'+total+' assigned copies · '+covered+' with saved card metadata</p>'+(covered<total?'<p class="muted">Incomplete card data: roles and themes may be undercounted.</p>':'')+'<h3>Strategy at a Glance</h3>'+(explicit.length?'<p><b>Your stated strategy:</b> '+esc(explicit.join(' · '))+'</p>':'<p>No explicit strategy notes set.</p>')+'<p><b>Detected strategy signals:</b> '+esc(themes.join(', ')||'Not enough evidence')+'</p><p>These signals suggest possible themes, not proven interactions or win conditions.</p><h3>Understanding Your Commander</h3>'+leaderHtml+'<h3>Deck Composition</h3><div class="primer173Metrics">'+roleKeys.map(k=>'<div><strong>'+counts[k]+'</strong><small>'+esc(labels[k])+'</small></div>').join('')+'</div><p class="muted">Counts use saved card metadata; roles can overlap. Commander cards are counted here only if assigned.</p><h3>Key Cards by Role</h3>'+(groups||'<p>No role candidates detected from saved data.</p>')+'<p class="muted">Candidates are selected by detected role, assigned quantity and mana value, not a verified strategic ranking.</p><h3>Coming in later primer updates</h3><p class="muted">Opening hands, gameplay sequencing, documented combos, win conditions and personal notes.</p>';b.querySelectorAll('[data-pname]').forEach(btn=>btn.addEventListener('click',()=>{const c=rows.map(x=>x.c).concat(leaders).find(x=>x.id&&x.id===btn.dataset.pcard)||leaders.concat(rows.map(x=>x.c)).find(x=>x.name===btn.dataset.pname);if(c)open('<h2>'+esc(c.name)+'</h2>'+universal178Slot(c,true))}));}catch(e){console.error('Primer foundation',e);b.textContent='Primer could not load. Your deck and collection are unchanged.'}}
'''
css='''<style>#primer173Body h3{margin:18px 0 7px}#primer173Body p{overflow-wrap:anywhere}#primer173Body .primer173Rules{white-space:pre-wrap;font-size:13px}.primer173Metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.primer173Metrics div{padding:8px;border:1px solid var(--secondary154,#9a7848);border-radius:8px;min-width:0}.primer173Metrics strong,.primer173Metrics small{display:block;overflow-wrap:anywhere}.primer173Metrics strong{font-size:20px;color:var(--primary154,#e1c18a)}.primer173Group{margin:8px 0}.primer173Group summary{cursor:pointer;padding:8px 0;color:var(--primary154,#e1c18a)}body #primer173Body .primer173Card{display:block;width:100%;text-align:left;margin:5px 0;padding:8px!important;white-space:normal;overflow-wrap:anywhere}.primer173Card small,.primer173Cost{display:block;font-size:12px;margin-top:3px}</style>'''
replacements=[('V17.2.8 Beta','V17.3.0 Beta'),("<script>(function(){const ids=['deckIntel','synergy15','combo172'","<script>"+patch+"</script><script>(function(){const ids=['deckIntel','primer173','synergy15','combo172'"),("short=['Overview','Synergy','Combos'","short=['Overview','Primer','Synergy','Combos'"),('combo172Init(host);if(deck!==active)','combo172Init(host);primer173Init(host);if(deck!==active)'),("if(selected==='combo172')combo172Paint()","if(selected==='combo172')combo172Paint();if(selected==='primer173')primer173Paint()"),('</body></html>',css+'</body></html>')]
for a,b in replacements:
    if s.count(a)!=1: raise SystemExit('Unexpected source anchor: '+a)
    s=s.replace(a,b,1)
with tempfile.TemporaryDirectory() as td:
    for i,m in enumerate(re.finditer(r'<script\b([^>]*)>([\s\S]*?)</script>',s,re.I)):
        if re.search(r'\bsrc\s*=|application/json',m[1]): continue
        f=Path(td)/f'{i}.js'; f.write_text(m[2],encoding='utf-8'); subprocess.run(['node','--check',str(f)],check=True)
out=p.parent/'v17.3.0'/ 'beta.html';out.parent.mkdir(exist_ok=True);out.write_text(s,encoding='utf-8');print(out)
